-- Polaris Complete Initial Schema (PostgreSQL 17)
-- All primary keys are UUID v7 generated by the application (or gen_random_uuid()).

CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    password_hash TEXT,
    google_sub VARCHAR(255) UNIQUE,
    display_name VARCHAR(255) NOT NULL,
    avatar_url TEXT NOT NULL DEFAULT '',
    status VARCHAR(32) NOT NULL DEFAULT 'active' CHECK (status IN ('invited', 'active', 'disabled')),
    mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    mfa_enforced BOOLEAN NOT NULL DEFAULT FALSE,
    totp_secret TEXT,
    mfa_backup_codes JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_active_email ON users(LOWER(email)) WHERE status != 'disabled';
CREATE INDEX IF NOT EXISTS idx_users_email ON users(LOWER(email));

CREATE TABLE IF NOT EXISTS user_sessions (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash VARCHAR(128) NOT NULL UNIQUE,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_user_sessions_user_id ON user_sessions(user_id);

CREATE TABLE IF NOT EXISTS email_verification_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_type VARCHAR(32) NOT NULL CHECK (token_type IN ('invite', 'password_reset', 'email_change')),
    token_hash VARCHAR(128) NOT NULL UNIQUE,
    new_email VARCHAR(255),
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_email_verification_tokens_user_id ON email_verification_tokens(user_id);

CREATE TABLE IF NOT EXISTS system_settings (
    id UUID PRIMARY KEY,
    default_hours_per_day NUMERIC(4,2) NOT NULL DEFAULT 8.00 CHECK (default_hours_per_day >= 1.00 AND default_hours_per_day <= 24.00),
    default_issue_template_id UUID,
    default_task_template_id UUID,
    require_mfa BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS system_smtp_settings (
    id UUID PRIMARY KEY,
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    host VARCHAR(255) NOT NULL DEFAULT '',
    port INTEGER NOT NULL DEFAULT 587,
    use_auth BOOLEAN NOT NULL DEFAULT FALSE,
    username VARCHAR(255) NOT NULL DEFAULT '',
    encrypted_password TEXT NOT NULL DEFAULT '',
    from_email VARCHAR(255) NOT NULL DEFAULT 'noreply@localhost',
    from_name VARCHAR(255) NOT NULL DEFAULT 'Polaris',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS system_allowed_domains (
    id UUID PRIMARY KEY,
    domain VARCHAR(255) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS user_fcm_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token TEXT NOT NULL UNIQUE,
    device_name VARCHAR(255) NOT NULL DEFAULT '',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_user_fcm_tokens_user_id ON user_fcm_tokens(user_id);

CREATE TABLE IF NOT EXISTS notifications (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    notification_type VARCHAR(32) NOT NULL CHECK (notification_type IN ('mention', 'assign')),
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    target_id UUID NOT NULL,
    project_id UUID NOT NULL,
    message TEXT NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_notifications_user_id_created ON notifications(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS personal_access_tokens (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    token_prefix VARCHAR(16) NOT NULL,
    scopes JSONB NOT NULL DEFAULT '[]'::jsonb,
    expires_at TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_pat_token_hash ON personal_access_tokens(token_hash);
CREATE INDEX IF NOT EXISTS idx_pat_user_id ON personal_access_tokens(user_id);

CREATE TABLE IF NOT EXISTS webauthn_credentials (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    credential_id BYTEA NOT NULL UNIQUE,
    public_key BYTEA NOT NULL,
    attestation_type VARCHAR(50) NOT NULL DEFAULT 'none',
    aaguid BYTEA,
    sign_count BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_webauthn_credentials_user_id ON webauthn_credentials(user_id);

CREATE TABLE IF NOT EXISTS mfa_challenges (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    temp_token_hash VARCHAR(128) NOT NULL UNIQUE,
    webauthn_challenge VARCHAR(128),
    totp_setup_secret TEXT,
    failed_attempts INT NOT NULL DEFAULT 0,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_mfa_challenges_user_id ON mfa_challenges(user_id);

CREATE TABLE IF NOT EXISTS projects (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    hours_per_day NUMERIC(4,2) NOT NULL DEFAULT 8.00 CHECK (hours_per_day >= 1.00 AND hours_per_day <= 24.00),
    default_issue_template_id UUID,
    default_task_template_id UUID,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS groups (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_groups_project_id ON groups(project_id);

CREATE TABLE IF NOT EXISTS group_members (
    id UUID PRIMARY KEY,
    group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (group_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_group_members_user_id ON group_members(user_id);

CREATE TABLE IF NOT EXISTS system_permissions (
    id UUID PRIMARY KEY,
    subject_type VARCHAR(32) NOT NULL CHECK (subject_type IN ('user', 'group')),
    subject_id UUID NOT NULL,
    permission VARCHAR(64) NOT NULL CHECK (permission IN ('create_project', 'delete_project', 'manage_system')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (subject_type, subject_id, permission)
);
CREATE INDEX IF NOT EXISTS idx_system_permissions_subject ON system_permissions(subject_type, subject_id);

CREATE TABLE IF NOT EXISTS project_members (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    subject_type VARCHAR(32) NOT NULL CHECK (subject_type IN ('user', 'group')),
    subject_id UUID NOT NULL,
    role VARCHAR(32) NOT NULL CHECK (role IN ('admin', 'editor', 'viewer')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (project_id, subject_type, subject_id)
);
CREATE INDEX IF NOT EXISTS idx_project_members_project_id ON project_members(project_id);
CREATE INDEX IF NOT EXISTS idx_project_members_subject ON project_members(subject_type, subject_id);

CREATE TABLE IF NOT EXISTS statuses (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    display_order INTEGER NOT NULL CHECK (display_order >= 1 AND display_order <= 10),
    name VARCHAR(255) NOT NULL,
    color VARCHAR(32) NOT NULL DEFAULT '#64748b',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_statuses_system_order ON statuses(display_order) WHERE project_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_statuses_project_order ON statuses(project_id, display_order) WHERE project_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS types (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    color VARCHAR(32) NOT NULL DEFAULT '#6366f1',
    display_order INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_types_project_id ON types(project_id);

CREATE TABLE IF NOT EXISTS labels (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    color VARCHAR(32) NOT NULL DEFAULT '#3b82f6',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_labels_project_id ON labels(project_id);

CREATE TABLE IF NOT EXISTS custom_field_definitions (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    name VARCHAR(255) NOT NULL,
    field_type VARCHAR(32) NOT NULL CHECK (field_type IN ('text_single', 'text_multi', 'markdown', 'number', 'date', 'radio', 'checkbox', 'select', 'user_group')),
    options_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_custom_field_defs_project ON custom_field_definitions(project_id, target_type);

CREATE TABLE IF NOT EXISTS templates (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_templates_project ON templates(project_id, target_type);

CREATE TABLE IF NOT EXISTS template_rows (
    id UUID PRIMARY KEY,
    template_id UUID NOT NULL REFERENCES templates(id) ON DELETE CASCADE,
    row_order INTEGER NOT NULL,
    columns_count INTEGER NOT NULL CHECK (columns_count >= 1 AND columns_count <= 3),
    UNIQUE (template_id, row_order)
);

CREATE TABLE IF NOT EXISTS template_fields (
    id UUID PRIMARY KEY,
    template_row_id UUID NOT NULL REFERENCES template_rows(id) ON DELETE CASCADE,
    column_order INTEGER NOT NULL CHECK (column_order >= 1 AND column_order <= 3),
    field_source VARCHAR(32) NOT NULL CHECK (field_source IN ('standard', 'custom')),
    field_key VARCHAR(128) NOT NULL,
    is_hidden BOOLEAN NOT NULL DEFAULT FALSE,
    is_restricted BOOLEAN NOT NULL DEFAULT FALSE,
    allow_owner_view BOOLEAN NOT NULL DEFAULT TRUE,
    allow_owner_edit BOOLEAN NOT NULL DEFAULT TRUE,
    view_subjects_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    edit_subjects_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    UNIQUE (template_row_id, column_order)
);

CREATE TABLE IF NOT EXISTS sprints (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    goal TEXT,
    start_date DATE,
    end_date DATE,
    status VARCHAR(20) NOT NULL DEFAULT 'planned',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_sprints_project_id ON sprints(project_id);
CREATE INDEX IF NOT EXISTS idx_sprints_status ON sprints(project_id, status);

CREATE TABLE IF NOT EXISTS issues (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    template_id UUID REFERENCES templates(id) ON DELETE SET NULL,
    type_id UUID REFERENCES types(id) ON DELETE SET NULL,
    owner_user_id UUID NOT NULL REFERENCES users(id),
    state VARCHAR(32) NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'closed')),
    title VARCHAR(500) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    display_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_issues_project_id ON issues(project_id, display_order);
CREATE INDEX IF NOT EXISTS idx_issues_type_id ON issues(type_id);

CREATE TABLE IF NOT EXISTS tasks (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    issue_id UUID NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
    template_id UUID REFERENCES templates(id) ON DELETE SET NULL,
    type_id UUID REFERENCES types(id) ON DELETE SET NULL,
    sprint_id UUID REFERENCES sprints(id) ON DELETE SET NULL,
    story_points NUMERIC(6,2),
    owner_user_id UUID NOT NULL REFERENCES users(id),
    status_id UUID NOT NULL REFERENCES statuses(id),
    title VARCHAR(500) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    progress INTEGER NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
    planned_start_date DATE,
    planned_end_date DATE,
    actual_start_date DATE,
    actual_end_date DATE,
    planned_hours NUMERIC(8,2) CHECK (planned_hours IS NULL OR planned_hours >= 0),
    actual_hours NUMERIC(8,2) CHECK (actual_hours IS NULL OR actual_hours >= 0),
    planned_cost NUMERIC(14,2) CHECK (planned_cost IS NULL OR planned_cost >= 0),
    actual_cost NUMERIC(14,2) CHECK (actual_cost IS NULL OR actual_cost >= 0),
    kanban_order INTEGER NOT NULL DEFAULT 0,
    gantt_order INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (planned_start_date IS NULL OR planned_end_date IS NULL OR planned_start_date <= planned_end_date),
    CHECK (actual_start_date IS NULL OR actual_end_date IS NULL OR actual_start_date <= actual_end_date)
);
CREATE INDEX IF NOT EXISTS idx_tasks_project_id ON tasks(project_id);
CREATE INDEX IF NOT EXISTS idx_tasks_issue_id ON tasks(issue_id);
CREATE INDEX IF NOT EXISTS idx_tasks_status_id ON tasks(status_id);
CREATE INDEX IF NOT EXISTS idx_tasks_sprint_id ON tasks(sprint_id);
CREATE INDEX IF NOT EXISTS idx_tasks_type_id ON tasks(type_id);

CREATE TABLE IF NOT EXISTS task_assignees (
    id UUID PRIMARY KEY,
    task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    assignee_type VARCHAR(32) NOT NULL CHECK (assignee_type IN ('user', 'group')),
    assignee_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (task_id, assignee_type, assignee_id)
);
CREATE INDEX IF NOT EXISTS idx_task_assignees_task_id ON task_assignees(task_id);

CREATE TABLE IF NOT EXISTS task_dependencies (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    predecessor_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    successor_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    dependency_type VARCHAR(10) NOT NULL DEFAULT 'FS',
    lag_days INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_task_dep UNIQUE (predecessor_id, successor_id),
    CONSTRAINT chk_no_self_dep CHECK (predecessor_id != successor_id)
);
CREATE INDEX IF NOT EXISTS idx_task_deps_project_id ON task_dependencies(project_id);
CREATE INDEX IF NOT EXISTS idx_task_deps_pred ON task_dependencies(predecessor_id);
CREATE INDEX IF NOT EXISTS idx_task_deps_succ ON task_dependencies(successor_id);

CREATE TABLE IF NOT EXISTS item_labels (
    id UUID PRIMARY KEY,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    target_id UUID NOT NULL,
    label_id UUID NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (target_type, target_id, label_id)
);
CREATE INDEX IF NOT EXISTS idx_item_labels_target ON item_labels(target_type, target_id);

CREATE TABLE IF NOT EXISTS custom_field_values (
    id UUID PRIMARY KEY,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    target_id UUID NOT NULL,
    field_definition_id UUID NOT NULL REFERENCES custom_field_definitions(id) ON DELETE CASCADE,
    value_json JSONB NOT NULL DEFAULT 'null'::jsonb,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (target_type, target_id, field_definition_id)
);
CREATE INDEX IF NOT EXISTS idx_custom_field_values_target ON custom_field_values(target_type, target_id);

CREATE TABLE IF NOT EXISTS file_blobs (
    id UUID PRIMARY KEY,
    sha512_hash VARCHAR(128) NOT NULL UNIQUE,
    size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0 AND size_bytes <= 1073741824),
    mime_type VARCHAR(255) NOT NULL DEFAULT 'application/octet-stream',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS file_chunks (
    id UUID PRIMARY KEY,
    blob_id UUID NOT NULL REFERENCES file_blobs(id) ON DELETE CASCADE,
    chunk_index INTEGER NOT NULL,
    data BYTEA NOT NULL,
    UNIQUE (blob_id, chunk_index)
);
CREATE INDEX IF NOT EXISTS idx_file_chunks_blob_id ON file_chunks(blob_id, chunk_index);

CREATE TABLE IF NOT EXISTS attachments (
    id UUID PRIMARY KEY,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    target_id UUID NOT NULL,
    blob_id UUID NOT NULL REFERENCES file_blobs(id) ON DELETE RESTRICT,
    file_name VARCHAR(500) NOT NULL,
    uploaded_by UUID NOT NULL REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_attachments_target ON attachments(target_type, target_id);
CREATE INDEX IF NOT EXISTS idx_attachments_blob_id ON attachments(blob_id);

CREATE TABLE IF NOT EXISTS comments (
    id UUID PRIMARY KEY,
    target_type VARCHAR(32) NOT NULL CHECK (target_type IN ('issue', 'task')),
    target_id UUID NOT NULL,
    author_user_id UUID NOT NULL REFERENCES users(id),
    body TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_comments_target ON comments(target_type, target_id, created_at);

CREATE TABLE IF NOT EXISTS comment_mentions (
    id UUID PRIMARY KEY,
    comment_id UUID NOT NULL REFERENCES comments(id) ON DELETE CASCADE,
    mention_type VARCHAR(32) NOT NULL CHECK (mention_type IN ('user', 'group')),
    mention_id UUID NOT NULL,
    UNIQUE (comment_id, mention_type, mention_id)
);

CREATE TABLE IF NOT EXISTS activity_logs (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    entity_type VARCHAR(50) NOT NULL,
    entity_id UUID NOT NULL,
    action VARCHAR(50) NOT NULL,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    actor_id UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_activity_logs_project_id ON activity_logs(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_logs_entity ON activity_logs(entity_type, entity_id, created_at DESC);

CREATE TABLE IF NOT EXISTS wiki_pages (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    slug VARCHAR(255) NOT NULL,
    content TEXT NOT NULL DEFAULT '',
    parent_id UUID REFERENCES wiki_pages(id) ON DELETE SET NULL,
    sort_order INT NOT NULL DEFAULT 0,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    updated_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_wiki_project_slug UNIQUE (project_id, slug)
);
CREATE INDEX IF NOT EXISTS idx_wiki_pages_project_id ON wiki_pages(project_id, sort_order ASC);
CREATE INDEX IF NOT EXISTS idx_wiki_pages_parent_id ON wiki_pages(parent_id);

CREATE TABLE IF NOT EXISTS webhooks (
    id UUID PRIMARY KEY,
    project_id UUID REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    url TEXT NOT NULL,
    secret VARCHAR(128) NOT NULL,
    events JSONB NOT NULL DEFAULT '[]'::jsonb,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_by UUID NOT NULL REFERENCES users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_webhooks_project_id ON webhooks(project_id);

CREATE TABLE IF NOT EXISTS webhook_deliveries (
    id UUID PRIMARY KEY,
    webhook_id UUID NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE,
    event VARCHAR(64) NOT NULL,
    status_code INT,
    duration_ms INT NOT NULL DEFAULT 0,
    request_body JSONB,
    response_body TEXT,
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_webhook_id ON webhook_deliveries(webhook_id);

CREATE TABLE IF NOT EXISTS inbound_webhooks (
    id UUID PRIMARY KEY,
    project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    secret VARCHAR(255) NOT NULL,
    default_issue_id UUID REFERENCES issues(id) ON DELETE SET NULL,
    default_status_id INT NOT NULL DEFAULT 1,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_inbound_webhooks_token_hash ON inbound_webhooks(token_hash);
CREATE INDEX IF NOT EXISTS idx_inbound_webhooks_project_id ON inbound_webhooks(project_id);

-- Initial system-wide default types (project_id IS NULL)
INSERT INTO types (id, project_id, name, color, display_order)
SELECT gen_random_uuid(), NULL, 'タスク', '#3b82f6', 1
WHERE NOT EXISTS (SELECT 1 FROM types WHERE project_id IS NULL AND name = 'タスク');

INSERT INTO types (id, project_id, name, color, display_order)
SELECT gen_random_uuid(), NULL, 'バグ', '#ef4444', 2
WHERE NOT EXISTS (SELECT 1 FROM types WHERE project_id IS NULL AND name = 'バグ');

INSERT INTO types (id, project_id, name, color, display_order)
SELECT gen_random_uuid(), NULL, '機能要望', '#10b981', 3
WHERE NOT EXISTS (SELECT 1 FROM types WHERE project_id IS NULL AND name = '機能要望');

INSERT INTO types (id, project_id, name, color, display_order)
SELECT gen_random_uuid(), NULL, '改善', '#f59e0b', 4
WHERE NOT EXISTS (SELECT 1 FROM types WHERE project_id IS NULL AND name = '改善');
